import{_ as l,o as t,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const d=JSON.parse('{"title":"写作课作业-089","description":"","frontmatter":{"date":"2020-10-22T19:37:54","title":"写作课作业-089","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/089.md","filePath":"posts/homework/089.md"}'),i={name:"posts/homework/089.md"};function p(r,e,s,c,n,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《微信互联网平民创业》之《21.你这一辈子应该如何赚钱?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>根据多年的观察、研究、试错和总结，李笑来认为赚钱的方式无非以下三种:</p><ul><li>用时间赚钱;</li><li>用金钱赚钱;</li><li>用金钱和时间一起赚钱......</li></ul></blockquote><blockquote><p>一般来说，一个人逐步提高自己收入的途径无非大概如下：</p><ul><li>通过「把份内的事情做好」，不断提高自己的时间单价；</li><li>通过作销售，把笔自己更强的人的同一份时间销售很多次；</li><li>通过学习相应的技能，写书、讲课，甚至作出自己的产品，把自己的同一份时间销售很多次；</li><li>当自己的收入有了超过生活必需之时，把多余的部分拿出来，攒到一起，开始做投资，用钱赚钱；</li><li>学习「定投策略」——因为他是唯一靠谱的、且悲反复证明的「同时用钱和时间去赚钱」的策略……</li></ul></blockquote><blockquote><p>无论是哪一个层次，都需要很久才能看到真正收益的……</p><p>「定投策略」事实上并不是非要把前面的几个层次全都做完才能开始做的，它是唯一不需要练习的技能</p></blockquote><blockquote><p>人生无非是认真选择定投标的而已。</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>因为加入定投践行群，自己从只有「用时间赚钱」的方式，开始有了「用钱和时间赚钱」的方式。</p><p>虽然践行群里，笑来老师多次强调销售，但是自己就是没有开始，虽说开始了不一定会有收入，但是经过一段的时间的打磨肯定会有收获的。现在一年多了，自己也有了收益，如果还不开始那是真的傻。那天看到践行群其实有很多人也都是没有销售门票的，嗯，我不孤单，如果我销售一张，我就成功了。</p><p>自己是做软件开发的，其实在这个行业应该是能比较容易的去完成一款产品的，但自己为什么迟迟没能做出一个呢？因为需要做很久，而自己还没能像一个猛人那样思考，去行动——「猛人勇于去做做很久才能看到收益的事情」。</p><p>自己加入了BOX践行群，也认同BOX践行群的价值观：「读书、健身、投资、帮朋友、陪家人」，那自己就应该定投下去，即使慢，也应该持续的做下去。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',18)])])}const h=l(i,[["render",p]]);export{d as __pageData,h as default};
